(r, big) => {
  const nd = v => ({ v, L: null, R: null });
  const put = (t, x, b) => { if (!t) return x; let c = t; for (;;) { const k = r.bool(b) ? "L" : "R"; if (!c[k]) { c[k] = x; return t; } c = c[k]; } };
  const rnd = (n, V, b) => { let t = null; for (let i = 0; i < n; i++) t = put(t, nd(V()), b); return t; };
  const deep = (len, n, V) => { const t = nd(V()); let c = t; for (let i = 1; i < len; i++) { const k = r.bool() ? "L" : "R"; c[k] = nd(V()); c = c[k]; } for (let i = len; i < n; i++) put(c, nd(V()), 0.5); return t; };
  const ser = t => { const o = [], q = [t]; for (let i = 0; i < q.length; i++) { const x = q[i]; if (x) { o.push(x.v); q.push(x.L, x.R); } else o.push(null); } while (o.length && o[o.length - 1] === null) o.pop(); return o; };
  if (big) return [ser(r.bool() ? deep(r.int(300, 450), 20000, () => r.int(-1000, 1000)) : rnd(20000, () => r.int(-1000, 1000), 0.5))];
  return [ser(rnd(r.int(0, 10), () => r.int(-9, 9), r.pick([0.5, 0.5, 0.3, 0.7])))];
}

