function rightView(root: TreeNode | null): number[] {
  const seen: number[] = [];
  let level: TreeNode[] = root ? [root] : [];
  while (level.length) {
    seen.push(level[level.length - 1].val);
    const next: TreeNode[] = [];
    for (const n of level) {
      if (n.left) next.push(n.left);
      if (n.right) next.push(n.right);
    }
    level = next;
  }
  return seen;
}

