class Solution:
    def rightView(self, root: Optional[TreeNode]) -> List[int]:
        seen = []
        queue = deque([root] if root else [])
        while queue:
            for i in range(len(queue)):
                node = queue.popleft()
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)
            seen.append(node.val)  # the last node of this level
        return seen

