function rightView(root: TreeNode | null): number[] {
  const seen: number[] = [];
  const walk = (n: TreeNode | null, depth: number): void => {
    if (!n) return;
    if (depth === seen.length) seen.push(n.val); // first arrival at this depth
    walk(n.right, depth + 1);
    walk(n.left, depth + 1);
  };
  walk(root, 0);
  return seen;
}

